import { Request, Response, Router } from "express";
import { CreateOrderInput, CreateProductInput } from "../application/dtos";
import { InventoryService } from "../application/inventory-service";
import { OrderService } from "../application/order-service";
import { DomainError, NotFoundError } from "../domain/errors";
import { OrderState } from "../domain/order";

const ORDER_STATES: readonly OrderState[] = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"];

export class OrderController {
  public constructor(
    private readonly inventory: InventoryService,
    private readonly orders: OrderService,
  ) {}

  public router(): Router {
    const router = Router();
    router.post("/products", this.handle((request) => this.inventory.addProduct(this.productInput(request))));
    router.get("/products", this.handle(() => this.inventory.listProducts()));
    router.post("/orders", this.handle((request) => this.orders.placeOrder(this.orderInput(request))));
    router.get("/orders", this.handle((request) => this.orders.listOrders(this.queryState(request))));
    router.post("/orders/:id/pay", this.handle((request) => this.orders.advanceOrder(this.orderId(request), "paid")));
    router.post("/orders/:id/pack", this.handle((request) => this.orders.advanceOrder(this.orderId(request), "packed")));
    router.post("/orders/:id/ship", this.handle((request) => this.orders.advanceOrder(this.orderId(request), "shipped")));
    router.post("/orders/:id/deliver", this.handle((request) => this.orders.advanceOrder(this.orderId(request), "delivered")));
    router.post("/orders/:id/cancel", this.handle((request) => this.orders.cancelOrder(this.orderId(request))));
    return router;
  }

  private handle(action: (request: Request) => unknown) {
    return (request: Request, response: Response): void => {
      try {
        response.status(request.method === "POST" ? 201 : 200).json(action(request));
      } catch (error: unknown) {
        const status = error instanceof NotFoundError ? 404 : error instanceof DomainError ? 400 : 500;
        response.status(status).json({ error: error instanceof Error ? error.message : "Internal server error" });
      }
    };
  }

  private productInput(request: Request): CreateProductInput {
    const body: unknown = request.body;
    if (!this.isRecord(body)) throw new DomainError("Request body must be an object");
    return { id: body.id as string, name: body.name as string, stock: body.stock as number };
  }

  private orderInput(request: Request): CreateOrderInput {
    const body: unknown = request.body;
    if (!this.isRecord(body) || !Array.isArray(body.items)) throw new DomainError("Order body must include items");
    return {
      customerId: body.customerId as string,
      items: body.items.map((item) => {
        if (!this.isRecord(item)) throw new DomainError("Each order item must be an object");
        return { productId: item.productId as string, quantity: item.quantity as number };
      }),
    };
  }

  private queryState(request: Request): OrderState | undefined {
    const state = request.query.state;
    if (state === undefined) return undefined;
    if (typeof state !== "string" || !ORDER_STATES.includes(state as OrderState)) {
      throw new DomainError("state must be a valid order state");
    }
    return state as OrderState;
  }

  private orderId(request: Request): string {
    const id = request.params.id;
    if (typeof id !== "string" || !id) throw new DomainError("Order id is required");
    return id;
  }

  private isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null;
  }
}

