import express, { Express } from "express";
import { InventoryService } from "../application/inventory-service";
import { OrderService } from "../application/order-service";
import { InMemoryOrderRepository } from "./in-memory-order-repository";
import { InMemoryProductRepository } from "./in-memory-product-repository";
import { OrderController } from "./order-controller";

export function createServer(): Express {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  const inventory = new InventoryService(products);
  const orderService = new OrderService(orders, products);
  const app = express();
  app.use(express.json());
  app.use(new OrderController(inventory, orderService).router());
  return app;
}

export function startServer(port = Number(process.env.PORT) || 3000): void {
  createServer().listen(port, () => {
    console.log(`Order fulfilment API listening on port ${port}`);
  });
}

if (require.main === module) {
  startServer();
}

